// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        uint256 callerBalanceBefore = address(this).balance;
        c.sudicideAnyone();
        assertTrue(address(this).balance == callerBalanceBefore + balanceBefore);
    }
}
